import {section,table as baseTable,cite,topic,mountTopic,rangePlayback} from "./topic-tools.js";
import {texEq as eq,inlineMath as m} from "./math.js";
import {marginPath,rewardOptimum} from "./preferences-model.js";
export const preferencesMeta={slug:"post-training/preferences",title:"Preference Optimization",description:"Learn from comparisons: DPO ratios, reference policies, beta, data quality and alternatives without confusing offline fitting with online rewards.",date:"2026-06-08",updated:"2026-10-14",topicPath:["post-training"],tags:["DPO","preference optimization","RLHF","reference policy","beta","APO","ORPO","KTO"],kind:"dense-topic",prototype:true,visibility:"public",learningGoals:["Compute a response-level preference margin","Interpret beta under a declared objective","Choose feedback and detect overfitting"],related:["post-training/sft","training/objectives","math/information","training/data"]};
export const preferencesAliases=[];
export const preferencesSections=[["motivation","Compare behavior instead of copying it"],["pairs","Build a meaningful comparison"],["contract","Score the same response contract"],["margin","Measure improvement relative to a reference"],["example","A better ratio can hide a worse answer"],["gradient","Read the gradient without overclaiming"],["reference","Why the reference appears"],["beta","Two different questions about beta"],["implementation","Compute a stable response-level loss"],["alternatives","Choose the feedback before the acronym"],["tuning","A small controlled preference experiment"],["overfit","Stop on behavior, not pair loss"],["reasoning","Reasoning preferences need reliable outcomes"],["online","Offline, refreshed preferences and RL"],["checklist","Checks before trusting a preference gain"],["sources","Sources and original context"]];
const fmt=x=>Number(x.toFixed(4)).toString();
const table=(c,h,r)=>baseTable(c,h,r).replace('<div class="dense-table-wrap">','<div class="dense-table-wrap" tabindex="0" role="region" aria-label="Scrollable preference comparison">');
function bars(probs,labels){return "<div class='preference-bars'>"+probs.map((p,i)=>"<div><span>"+labels[i]+"</span><div class='preference-track'><span style='width:"+100*p+"%'></span></div><code>"+fmt(100*p)+"%</code></div>").join("")+"</div>";}
function marginBody(t=0,mode="split",beta=.1){
 const s=marginPath(t,mode,beta);
 return bars(s.probs,["Chosen","Rejected","Other"])+"<p>Assigned base probabilities [0.4,0.4,0.2]; reference [0.5,0.3,0.2]. Logit changes ["+s.change.map(fmt).join(",")+"]. t="+fmt(t)+", β="+fmt(beta)+".</p><p>Relative margin Δ="+fmt(s.margin)+"; βΔ="+fmt(s.z)+"; sigmoid="+fmt(s.p)+"; loss="+fmt(s.loss)+". Chosen log-probability gradient="+fmt(s.chosenGradient)+".</p><p>"+(s.probs[0]<.4-1e-12&&s.probs[1]<.4-1e-12?"Both named responses lost probability. Rejected fell faster, so their ratio can still improve.":s.probs[0]>.4+1e-12?"Chosen probability rose in this assigned path. That is not guaranteed for all model updates.":"Chosen probability is at or below its assigned starting value. Inspect the ratio and absolute probability separately.")+"</p><p>This parameter sweep is not gradient descent or a measured training trajectory. The other response absorbs normalization mass.</p>";
}
function betaBody(beta=.5){
 const s=rewardOptimum(beta);
 return bars(s.probs,["Reward +1","Reward 0","Reward −1"])+"<p>Fixed reward [1,0,−1]; reference [0.5,0.3,0.2]; β="+fmt(beta)+". Expected reward="+fmt(s.expected)+"; KL(policy || reference)="+fmt(s.kl)+" nats.</p><p>Objective E[r]−β KL="+fmt(s.objective)+". Increasing β pulls this exact fixed-reward optimum toward the reference. It does not describe one finite DPO optimizer step.</p>";
}
export function preferencesReader(link){
 const parts=[],add=(id,body)=>parts.push(section(id,preferencesSections.find(s=>s[0]===id)[1],body));
 const related=(s,t)=>"<a href='"+link(s)+"'>"+t+" →</a>";
 add("motivation","<p>Supervised fine-tuning imitates selected demonstrations. Preference optimization uses a different signal: for the same prompt, response A is better than response B. This can express style, helpfulness or reasoning quality without specifying one exact answer.</p><p>Begin with a useful assistant checkpoint and test whether comparative feedback improves it. Direct Preference Optimization (DPO) is a convenient baseline. It avoids an explicit learned reward model and an online rollout loop during its standard offline training.</p><p>This makes preference training a useful middle step between imitation and online RL. It is not always cheaper or more stable: long paired responses, reference scoring, poor labels and aggressive updates can still make a run expensive or unreliable. A working SFT interface remains a practical starting point, not an absolute requirement for every objective. "+related("post-training/sft","SFT and Adaptation")+"</p>");
 add("pairs","<p>A preference pair contains a prompt x, chosen response y+ and rejected response y−. Both responses must answer the same conditioned task. Record the labeling criterion: correctness, instruction compliance, brevity, safety or a deliberate combination.</p><p>If a chosen answer is correct but verbose and a rejected answer is concise but wrong, the label does not isolate verbosity. Conflicting criteria can teach inconsistent behavior. Preserve ties or ambiguous cases under an explicit policy instead of forcing arbitrary winners.</p><p>Keep evaluator provenance, model versions and generation budgets. Deduplicate prompts and response families before train/evaluation splitting. Near-identical responses can supply weak differences; easy obviously bad negatives can fail to teach the distinctions the deployed model needs.</p><p>Small preference sets can already be useful. Their value depends on coverage and label quality, not a universal minimum count. Start with a representative pilot rather than waiting for a huge labeling pipeline.</p>");
 add("contract","<p>Score each completion conditioned on the same prompt. Sum causal token log probabilities over the response mask, including the intended termination token. Exclude padding and prompt targets. Match templates, tokenizer IDs and one-position shifting between policy and reference.</p>"+eq(String.raw`\log\pi(y\mid x)=\sum_{t\in M}\log\pi(y_t\mid x,y_{<t})`,"M is the declared completion-token mask, including the intended ending. This is a sequence sum. Dividing by response length defines a different objective.")+"<p>A response can span thought channels and tool actions. Define which spans belong to its score before training. Do not include different histories in chosen and rejected prefixes while treating them as a simple comparison for one prompt.</p><p>Truncation can cut an answer or remove its ending. Check actual retained IDs and masks, not raw text lengths. The "+related("post-training/sft","SFT reader")+" covers the shared serialization, masking and parser contract.</p>");
 add("margin",eq(String.raw`\begin{aligned}\Delta&=\bigl[\log\pi_\theta(y_+\mid x)-\log\pi_\theta(y_-\mid x)\bigr]\\&\quad-\bigl[\log\pi_{\mathrm{ref}}(y_+\mid x)-\log\pi_{\mathrm{ref}}(y_-\mid x)\bigr]\end{aligned}`,"A positive Δ means the policy improved the chosen/rejected odds relative to the reference.")+eq(String.raw`L_{\mathrm{DPO}}=-\log\sigma(\beta\Delta)=\operatorname{softplus}(-\beta\Delta),\quad\beta>0`,"σ is sigmoid. Average this pair loss over the intended weighted dataset.")+"<p>The reference is frozen. At "+m(String.raw`\pi_\theta=\pi_{\mathrm{ref}}`)+", "+m(String.raw`\Delta=0`)+", preference probability is "+m(String.raw`\frac12`)+" and pair loss is "+m(String.raw`\log 2`)+". The two sequences need not have equal absolute probability at this point.</p><p>A lower loss means a better fitted comparison under this objective. It is not a direct measure of correctness, calibration or the probability of generating a useful answer.</p>");
 add("example","<p>Take three exhaustive toy responses: chosen, rejected and other. The reference assigns [0.5,0.3,0.2], while the initial policy assigns [0.4,0.4,0.2]. The initial margin is "+m(String.raw`-\log\frac53`)+", because the policy favors chosen less strongly than the reference.</p><figure class='topic-scene' data-preference-lab='margin'><h3>Follow the ratio and the absolute mass</h3><label>Assigned logit path<select aria-label='Assigned logit path'><option value='split'>Raise chosen, lower rejected logits</option><option value='down'>Lower both, rejected twice as fast</option></select></label><label>Path position<input aria-label='Preference path position' type='range' min='-40' max='40' step='1' value='0'></label><label>Pair beta<select aria-label='Pair beta'><option value='.01'>0.01</option><option value='.1' selected>0.1</option><option value='.5'>0.5</option><option value='1'>1</option></select></label><div class='dense-actions'><button data-play>Play</button><button data-reset>Replay</button></div><div data-body>"+marginBody()+"</div><figcaption>Exact normalized toy probabilities; path position is not training time.</figcaption></figure><p>On the second path at "+m(String.raw`t=4`)+", both named answers have lower probability than 0.4. Rejected fell faster, so Δ still rises. This demonstrates why ratio improvement alone does not prove that chosen answers became more likely. The example is a possible normalized distribution change, not a prediction of every DPO run.</p>");
 add("gradient",eq(String.raw`\begin{aligned}\frac{\partial L}{\partial\log\pi_\theta(y_+\mid x)}&=-\beta\,\sigma(-\beta\Delta)\\\frac{\partial L}{\partial\log\pi_\theta(y_-\mid x)}&=+\beta\,\sigma(-\beta\Delta)\end{aligned}`,"These are score-coordinate partial derivatives, not independent controls over all model probabilities.")+"<p>A misordered comparison has greater pressure than an already satisfied comparison. Both sequence scores share model parameters. Normalization, competing examples and parameter geometry determine the actual update.</p><p>Monitor absolute chosen/rejected log probabilities as well as the margin. The mathematical partial derivatives do not guarantee that one optimizer step increases every preferred sequence's probability. A useful preference model must improve deployed behavior beyond the training pairs.</p>");
 add("reference","<p>The reference anchors the comparison to an existing policy. The conventional regularized objective maximizes "+m(String.raw`\mathbb E[r]-\beta D_{\mathrm{KL}}(\pi\Vert\pi_{\mathrm{ref}})`)+". For fixed reward "+m(String.raw`r`)+", the optimum is proportional to "+m(String.raw`\pi_{\mathrm{ref}}\exp\left(\frac r\beta\right)`)+".</p>"+eq(String.raw`r(x,y)=\beta\log\frac{\pi^*(y\mid x)}{\pi_{\mathrm{ref}}(y\mid x)}+\beta\log Z(x)`,"A prompt-only normalization term cancels between two answers.")+"<p>Substituting this relationship into a Bradley–Terry comparison yields the DPO pair loss. This connection requires its preference-model and support assumptions. Finite data and finite optimization do not guarantee recovery of a perfect online-RL solution. "+cite("https://arxiv.org/html/2305.18290v3","DPO derivation")+"</p><p>Keep the reference truly frozen, including adapters and trainable vocabulary rows. Disabling an adapter recovers the intended reference only if no shared base state changed. Cached reference scores are valid only for the same reference, tokens and score masks.</p>");
 add("beta","<p>Two statements about β answer different questions. With fixed reward in "+m(String.raw`\mathbb E[r]-\beta D_{\mathrm{KL}}(\pi\Vert\pi_{\mathrm{ref}})`)+", larger β penalizes departure more strongly. In the DPO classifier, β also scales the margin and its gradient.</p><figure class='topic-scene' data-preference-lab='beta'><h3>Change the fixed-reward optimum</h3><label>KL coefficient beta<input aria-label='KL coefficient beta' type='range' min='5' max='200' step='1' value='50'></label><div data-body>"+betaBody()+"</div><figcaption>Exact three-response optimization with fixed reward; not a measured DPO run.</figcaption></figure><p>At "+m(String.raw`\Delta=0`)+", the chosen score derivative is "+m(String.raw`-\frac{\beta}{2}`)+". Increasing β therefore increases that local gradient magnitude, even though larger β means stronger anchoring in the fixed-reward optimum. There is no contradiction: one describes a local training step, the other a solved objective.</p><p>Read the actual loss before interpreting configuration values. Some methods use inverse-temperature or margin conventions. The original playbook-based note suggests β in [0.01,0.5] as a search region, not a universal default or a guarantee of monotonic measured KL.</p>");
 add("implementation","<p>Compute token log probabilities with log-softmax, select response tokens and sum them per sequence. Score chosen and rejected with both policy and frozen reference. Then form the relative margin.</p><pre><code>with no_grad():\n    ref_plus, ref_minus = response_logps(reference, batch)\npi_plus, pi_minus = response_logps(policy, batch)\nmargin = (pi_plus - pi_minus) - (ref_plus - ref_minus)\nloss_per_pair = -logsigmoid(beta * margin)\nloss = loss_per_pair.mean()\nloss.backward()</code></pre><p>This is conceptual code. The helper must apply one shift and the exact completion masks. Use stable log-sigmoid rather than taking log(sigmoid(z)) after saturation. Accumulate long sequence sums with adequate precision.</p><p>State pair weights and reduction denominators. Do not silently replace sequence sums with token means when moving to another trainer. Check dropout policy and reference determinism before caching scores.</p>");
 add("alternatives","<p>After a working DPO baseline, change the objective only to answer a concrete feedback or optimization question. Alternative acronyms do not establish superiority.</p>"+table("Different objectives need different feedback and conventions",["Family","Useful distinction","Check"],[["DPO","Paired relative log-ratio fitting","Frozen reference and sequence sums"],["APO","Anchored probability movement","Zero/down variant and winner quality"],["ORPO","Chosen-response likelihood plus odds-ratio penalty","Length-normalized score and coefficient convention"],["KTO","Desirable/undesirable individual feedback","Reference baseline and label balance"]])+"<p>APO separates cases where winners deserve promotion from cases where even winners should lose probability, with losers reduced more. The TRL zero/down implementations encode different assumptions. "+cite("https://huggingface.co/docs/trl/main/en/dpo_trainer","APO configuration")+"</p><p>ORPO combines supervised learning on chosen responses with an odds-ratio preference term, without a separate reference policy. It is not DPO with reference subtraction deleted. Its score normalization and penalty weight form a separate contract. "+cite("https://arxiv.org/abs/2403.07691","ORPO")+"</p><p>KTO accepts individual desirable/undesirable labels rather than requiring paired rankings. Its prospect-theoretic objective uses a reference-relative baseline and separate label weighting. Use it when that feedback is available, not because every binary label is equally reliable. "+cite("https://arxiv.org/html/2402.01306v4","KTO")+"</p>");
 add("tuning","<p>First verify pair direction, masks and reference identity on a few examples. At initialization equal to the reference, confirm zero margins. Reversing chosen/rejected should reverse the margin. Identical responses should supply no directional distinction.</p><p>The playbook-based original suggests learning rates roughly 5–20 times lower than SFT. Treat this as a sweep starting point. Effective batch, adapter/full tuning, response lengths, objective and optimizer affect the useful scale.</p><p>Keep a matched pilot: same base, examples, target preprocessing, update budget and held-out generation settings. Sweep learning rate and β jointly. A comparison that tunes one objective thoroughly but gives another a default is not a clean objective ablation.</p><p>Record the intended data coverage and evaluation budget. A modest set can reveal a useful gain; it cannot establish broad safety or reasoning reliability by size alone.</p>");
 add("overfit","<p>Preference fitting can overfit quickly. The original practical note warns that this can happen around one epoch. That is a warning to evaluate early, not a universal stopping threshold.</p><p>Track held-out pair accuracy and generated behavior separately. A larger implicit reward margin can coexist with worse response quality or lower preferred-response probability. The learned reward is reference-relative, not a calibrated external evaluator.</p><p>Short runs over shuffled slices can reduce repeated exposure during iteration. They do not remove leakage, bad labels or selection bias. Keep held-out prompts out of labeling and training decisions. Select checkpoints by downstream behavior under fixed evaluation conditions, not the lowest training loss.</p>");
 add("reasoning","<p>Preference training is not limited to tone or refusals. Correctness-based pairs can improve reasoning behavior and may make immediate escalation to online RL unnecessary. This is a practical opportunity, not a claim that offline pairs discover every missing strategy.</p><p>Check the criterion that selects the winner. Final-answer verification can miss wrong intermediate reasoning. A stylistic judge can favor long confident traces. Process labels and reliable final verifiers express different preferences.</p><p>Compare accuracy, response length, termination and general capabilities. Preserve failed actions as context when they explain recovery, but do not call a malformed successful trajectory a clean demonstration.</p>");
 add("online","<p>Offline preference optimization fits a fixed set. Iterative or on-policy variants refresh candidate answers and labels as the model changes. New comparisons can target current failures and reduce mismatch with an old candidate distribution.</p><p>Refreshing data costs generation, evaluation and provenance tracking. It does not make preference fitting identical to online policy-gradient RL. The update objective and the data-collection policy are separate choices.</p><p>Use online RL when sampled actions and reward feedback provide something static comparisons do not capture, especially environment interaction. It brings reward design, credit assignment, rollout versioning and throughput constraints. This is not a mandatory final stage for every assistant.</p>"+table("Feedback and collection are independent axes",["Setup","Feedback","Current-policy sampling"],[["Offline DPO","Fixed chosen/rejected pairs","Not required inside training"],["Refreshed preference rounds","New labeled comparisons","Used to refresh candidate data"],["Online policy gradients","Rewards/advantages on sampled actions","Normally central to collection"]]));
 add("checklist","<ol><li>Define the preference criterion and keep ambiguous cases explicit.</li><li>Verify identical prompts, templates, causal shifts and completion masks.</li><li>Freeze the intended reference and version cached scores.</li><li>Check margins, finite loss and gradient direction on tiny examples.</li><li>Run matched learning-rate/β sweeps; monitor absolute probabilities too.</li><li>Evaluate held-out generations early, including reasoning, length and stopping.</li><li>Refresh data or change objectives only for an observed limitation.</li></ol><p>"+related("training/objectives","Losses")+" owns logistic scoring and reductions. "+related("math/information","Information Theory")+" explains KL direction and coding cost. "+related("training/data","Training Data")+" covers mixture and leakage.</p>");
 add("sources","<p>"+cite("https://arxiv.org/html/2305.18290v3","DPO paper")+" · "+cite("https://huggingface.co/docs/trl/main/en/dpo_trainer","Current TRL DPO documentation")+" · "+cite("https://arxiv.org/abs/2403.07691","ORPO")+" · "+cite("https://arxiv.org/html/2402.01306v4","KTO")+" · "+cite("https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook","Smol Training Playbook")+"</p><p>The small distributions are exact illustrations. Learning-rate, β and epoch suggestions are source-attributed heuristics, not reconstructed experiments or universal guarantees.</p><p>"+related("post-training/rl","Reinforcement Learning")+" · "+related("post-training/distillation","Distillation")+" · "+related("post-training/reasoning","Reasoning Models")+"</p>");
 return topic(preferencesMeta,preferencesSections,"What a comparison teaches, what a likelihood ratio hides, and when fixed preference data stops being enough.",parts.join("\n"));
}
export function mountPreferences(scope=document){mountTopic(scope,preferencesMeta.slug,article=>{
 const margin=article.querySelector("[data-preference-lab='margin']"),selects=[...margin.querySelectorAll("select")],input=margin.querySelector("input"),draw=()=>{margin.querySelector("[data-body]").innerHTML=marginBody(Number(input.value)/10,selects[0].value,Number(selects[1].value));};
 const p=rangePlayback(article,margin,draw,18000);for(const s of selects)s.addEventListener("change",()=>{p.stop();draw();});
 const lab=article.querySelector("[data-preference-lab='beta']"),beta=lab.querySelector("input");beta.addEventListener("input",()=>{lab.querySelector("[data-body]").innerHTML=betaBody(Number(beta.value)/100);});
});}
preferencesMeta.searchText=preferencesReader(()=> "").replace(/<[^>]*>/g," ");
